for _, z in ipairs(ZONES) do
	ObviGuide.Guide(function(g)
		g.title = "Explore " .. z.zone
		g.group = z.folder
		g.id    = "obvi-explore-" .. z.id
		g.only  = z.only
		g.challenge = z.id
		for _, a in ipairs(z.areas) do
			g:Step(function(s)
				s:Goto(a[6] or z.map, a[2], a[3])
				s:Explore(z.id, a[1], { a[4], a[5] })
			end)
		end
	end)
end

-- one step: the parts still to finish (each line goes once its part is finished), each opening its guide
for _, m in ipairs(METAS) do
	ObviGuide.Guide(function(g)
		g.title = m.title
		g.group = m.folder
		g.id    = "obvi-explore-" .. m.id
		g.challenge = m.id
		g:Step(function(s)
			s:Say("Still to finish; click one to open its guide.")
			for _, p in ipairs(m.parts) do s:Challenge(p[1], "obvi-explore-" .. p[1], p[2]) end
		end)
	end)
end
